export const feudDefaults={feudEnabled:true,feudRate:1,feudSceneDurations:{},feudLayerEdits:{},feudSourceBindings:{},feudCameraX:0,feudCameraY:0,feudCameraZoom:0,feudCloudWind:18,feudCloudEvolution:.11,feudFireStrength:1,feudEyeStrength:1,feudTitle:'THE TOWN OF BENT NECKS',feudChapter:'CHAPTER 4:',feudTitleSize:51,feudTitleColor:'#ffe595',feudTitleScatter:420,feudTitleBlur:22,feudIllustrationLabel:true};
export const feudSources={feudPortrait:'feud-frontal-v83.png',feudHeadA:'feud-head-views-v83.png',feudHeadB:'feud-head-views-v83.png',feudPersonA:'shelter-cutouts-v81.png',feudPersonB:'shelter-cutouts-v81.png',feudPersonC:'shelter-cutouts-v81.png',feudPersonD:'shelter-cutouts-v81.png',feudFactory:'period-factory-v65.png',feudGround:'dark-earth-v63.png',feudBrandA:'adidas-wordmark.svg',feudBrandB:'puma-lockup.svg',feudFire:'trial-fire-v82.png',feudShoeA:'salvage-brown-shoe-v58.png',feudShoeB:'salvage-cream-shoe-v58.png',feudCourt:'trial-environments-audience-v82.png',feudWitnessA:'trial-people-b-v82.png',feudWitnessB:'trial-people-b-v82.png'};
export const feudStages=[['court-continuation',655,658.6],['witness-slices',658.6,662.7],['face-pullback',662.7,669.7],['allegation-collage',669.7,675.3],['collage-question',675.3,677.2],['question-hold',677.2,682],['metal-heads',682,688.5],['heads-factory-handoff',688.5,691.5],['factory-split',691.5,695.5],['company-reveal',695.5,698.2666666666667],['revenge-fire',698.2666666666667,706],['fade-black',706,707.5],['black-hold',707.5,710.0333333333333],['chapter-assembly',710.0333333333333,712],['chapter-hold',712,715]].map(([id,from,to])=>({id:'feud-'+id,from,to,duration:to-from,label:id.replaceAll('-',' ')}));
export const feudLayerCatalog=[...Object.keys(feudSources).map(id=>({id,slot:id,label:id})),...['clouds','question','head-a','head-b','eye-a','eye-b','factory-a','factory-b','rail','ground','fire-front','fire-back','chapter-title','chapter-label','chapter-shoes','illustration-label'].map(id=>({id,slot:null,label:id}))];
const clamp=x=>Math.max(0,Math.min(1,x)),mix=(a,b,q)=>a+(b-a)*q,ease=x=>{x=clamp(x);return x*x*(3-2*x)},span=(t,a,b)=>ease((t-a)/(b-a));
export function validateFeud(input={}){const f={...feudDefaults,...input};for(const k of ['feudEnabled','feudIllustrationLabel'])if(typeof f[k]!=='boolean')throw Error('Invalid flag '+k);for(const k of ['feudSceneDurations','feudLayerEdits','feudSourceBindings'])if(!f[k]||typeof f[k]!=='object'||Array.isArray(f[k]))throw Error('Expected object '+k);for(const[k,v]of Object.entries(feudDefaults))if(typeof v==='number'&&!Number.isFinite(f[k]))throw Error('Finite '+k);if(f.feudRate<.05||f.feudRate>4||f.feudCameraZoom<=-.8||f.feudFireStrength<0||f.feudFireStrength>2||f.feudEyeStrength<0||f.feudEyeStrength>2||f.feudTitleSize<8||f.feudTitleSize>200||f.feudTitleBlur<0||f.feudTitleScatter<0)throw Error('Invalid range');for(const k of ['feudTitle','feudChapter','feudTitleColor'])if(typeof f[k]!=='string'||f[k].length>200)throw Error('Invalid text');for(const[id,d]of Object.entries(f.feudSceneDurations))if(!feudStages.some(s=>s.id===id)||!Number.isFinite(d)||d<.05||d>300)throw Error('Invalid duration');for(const[id,e]of Object.entries(f.feudLayerEdits)){if(!feudLayerCatalog.some(s=>s.id===id)||!e||typeof e!=='object'||Array.isArray(e))throw Error('Invalid layer');if(e.visible!==undefined&&typeof e.visible!=='boolean')throw Error('Invalid visibility');for(const k of ['x','y','scale','rotation','opacity','blur','depth'])if(e[k]!==undefined&&(!Number.isFinite(e[k])||['scale','depth'].includes(k)&&e[k]<=0||k==='blur'&&e[k]<0||k==='opacity'&&(e[k]<0||e[k]>1)))throw Error('Invalid transform');sampleObjectMotion(0,e.motion||{});}for(const[k,v]of Object.entries(f.feudSourceBindings))if(!(k in feudSources)||typeof v!=='string')throw Error('Invalid binding');return true;}
export function feudDuration(input={}){const f={...feudDefaults,...input};return feudStages.reduce((a,s)=>a+(f.feudSceneDurations[s.id]??s.duration),0)/f.feudRate;}
export function feudSourceToLocal(source,input={}){const f={...feudDefaults,...input};let n=0;for(const s of feudStages){const d=f.feudSceneDurations[s.id]??s.duration;if(source<=s.to)return(n+d*clamp((source-s.from)/s.duration))/f.feudRate;n+=d;}return n/f.feudRate;}
export function feudState(age,input={}){const f={...feudDefaults,...input};let n=0;for(const s of feudStages){const d=f.feudSceneDurations[s.id]??s.duration;if(age*f.feudRate<n+d)return{source:mix(s.from,s.to,clamp((age*f.feudRate-n)/d)),id:s.id};n+=d;}return{source:715,id:feudStages.at(-1).id};}
const crops={feudPersonA:[0,0,1/3,.5],feudPersonB:[1/3,0,1/3,.5],feudPersonC:[2/3,0,1/3,.5],feudPersonD:[0,.5,1/3,.5],feudCourt:[.5,.5,.5,.5],feudWitnessA:[0,.5,.5,.5],feudWitnessB:[.5,0,.5,.5]},cache=new WeakMap();
function media(images,f,id,view){const im=images[f.feudSourceBindings[id]||id];if(!im||im.tagName==='VIDEO'&&im.readyState<2)return null;if(f.feudSourceBindings[id]||im.tagName==='VIDEO')return im;let m=cache.get(im);if(!m)cache.set(im,m=new Map());const key=id+':'+(view??'');if(m.has(key))return m.get(key);let r=crops[id];if(id==='feudHeadA'||id==='feudHeadB')r=[(view??1)/3,id==='feudHeadA'?0:.5,1/3,.5];if(!r)return im;const cv=Object.assign(document.createElement('canvas'),{width:Math.round(im.width*r[2]),height:Math.round(im.height*r[3])}),c=cv.getContext('2d');c.drawImage(im,im.width*r[0],im.height*r[1],im.width*r[2],im.height*r[3],0,0,cv.width,cv.height);m.set(key,cv);return cv;}
function layer(c,f,id,t,r,fn){const e=f.feudLayerEdits[id]||{};if(e.visible===false)return;const m=sampleObjectMotion((t-655)/f.feudRate,e.motion||{}),[x,y,w,h]=r,z=1+f.feudCameraZoom;c.save();c.translate(x+w/2+(e.x||0)+m.x-f.feudCameraX/(e.depth||2),y+h/2+(e.y||0)+m.y-f.feudCameraY/(e.depth||2));c.rotate(((e.rotation||0)+m.rotation)*Math.PI/180);c.scale((e.scale??1)*m.scale*z,(e.scale??1)*m.scale*z);c.globalAlpha*=(e.opacity??1)*m.opacity;if(e.blur)c.filter=`blur(${e.blur}px)`;fn(-w/2,-h/2,w,h);recordSceneAsset(c,{id:'feud:'+id,editKey:id,assetSlot:feudLayerCatalog.find(l=>l.id===id)?.slot,name:id,kind:'feud'},[-w/2,-h/2,w,h]);c.restore();}
function pic(c,images,f,id,t,x,y,w,h=0,view){const im=media(images,f,id,view);if(!im)return;h||=w*(im.videoHeight||im.height)/(im.videoWidth||im.width);layer(c,f,id,t,[x,y,w,h],(X,Y,W,H)=>c.drawImage(im,X,Y,W,H));}
function vignette(c,a=.65){const g=c.createRadialGradient(480,240,130,480,260,660);g.addColorStop(0,'#0000');g.addColorStop(1,`rgba(0,0,0,${a})`);c.fillStyle=g;c.fillRect(0,0,960,540);}
function atmosphere(c,f,t,mode='red'){layer(c,f,'clouds',t,[0,0,960,540],(x,y)=>{c.translate(x,y);paintLivingSky(c,t-655,{}, {skyWind:f.feudCloudWind,skyEvolution:f.feudCloudEvolution,skyColor:mode==='title'?'#170e24':'#62051c',skyCloudColor:'#11070e',skyLayers:1,skyDensity:.72,skyOpacity:.96,skySeed:83,skyScale:1.2,skyLight:.45});if(mode==='split'||mode==='title'){const g=c.createLinearGradient(0,0,960,0);g.addColorStop(0,mode==='title'?'#091d60bb':'#042b3fe8');g.addColorStop(mode==='title'?.42:.49,mode==='title'?'#0d126933':'#021d2bd8');g.addColorStop(mode==='title'?.72:.5,'#500a1900');g.addColorStop(1,'#72001d66');c.fillStyle=g;c.fillRect(0,0,960,540);}vignette(c);});}
function portrait(c,images,f,t,z=1){const w=1300*z,im=media(images,f,'feudPortrait');if(!im)return;layer(c,f,'feudPortrait',t,[480-w/2,240-w*.38,w,w],(x,y,W,H)=>{c.save();c.filter='brightness(.67) contrast(1.4)';c.drawImage(im,x,y,W,H);c.restore();});}
function people(c,images,f,t){const poses=[['feudPersonA',-20,350,300,0],['feudPersonB',140,365,300,0],['feudPersonC',690,350,300,0],['feudPersonD',470,350,310,1],['feudPersonA',325,390,240,1],['feudPersonB',595,400,235,1]];for(let i=0;i<poses.length;i++){const[id,x,y,w,gray]=poses[i],a=span(t,669.7+i*.06,671.2+i*.06);c.save();c.filter=gray?'grayscale(1)':'none';pic(c,images,f,id,t,x,y+(1-a)*230,w);c.restore();}}
function collage(c,images,f,t){portrait(c,images,f,t,mix(2.1,.79,span(t,662.8,670)));if(t>=669.7)people(c,images,f,t);}
let nested;function question(c,images,f,t){if(t<676.45){nested||=Object.assign(document.createElement('canvas'),{width:960,height:540});const cc=nested.getContext('2d');cc.clearRect(0,0,960,540);collage(cc,images,f,675.3);const q=span(t,675.3,676.45),k=mix(1,.13,q),r=mix(620,270,span(t,675.3,675.55))*k;layer(c,f,'question',t,[0,0,960,540],(x,y)=>{c.translate(x,y);c.beginPath();c.arc(480,270,r,0,Math.PI*2);c.clip();c.drawImage(nested,480-480*k,270-270*k,960*k,540*k);});return;}const build=span(t,676.45,677.2),sz=mix(210,155,span(t,677.2,682));layer(c,f,'question',t,[480-sz/2,270-sz*.6,sz,sz*1.2],(x,y,w,h)=>{const cv=Object.assign(document.createElement('canvas'),{width:240,height:300}),cc=cv.getContext('2d');cc.fillStyle='#fff';cc.textAlign='center';cc.textBaseline='middle';cc.font='800 285px Arial';cc.save();cc.beginPath();cc.rect(0,300*(1-build),240,300*build);cc.clip();cc.fillText('?',120,154);cc.restore();cc.beginPath();cc.arc(120,244,21,0,Math.PI*2);cc.fill();cc.globalCompositeOperation='source-in';const im=media(images,f,'feudPortrait');if(im)cc.drawImage(im,-30,-10,300,300);c.drawImage(cv,x,y,w,h);});}
function eye(c,f,id,t,x,y){layer(c,f,id,t,[x-42,y-14,84,28],(X,Y)=>{c.globalCompositeOperation='screen';c.globalAlpha*=f.feudEyeStrength;c.strokeStyle='#ff9d10';c.shadowColor='#ff5200';c.shadowBlur=13;c.lineWidth=3;for(let j=0;j<3;j++){c.beginPath();for(let i=0;i<14;i++){const px=X+i*6,py=Y+13+Math.sin(i*.8+t*19+j)*3*(i/14);i?c.lineTo(px,py):c.moveTo(px,py);}c.stroke();}c.shadowBlur=2;c.strokeStyle='#fff4a4';c.lineWidth=1;c.stroke();});}
function heads(c,images,f,t){const q=span(t,682,684.5),exit=span(t,688.5,690),turn=span(t,682.4,683.6),front=turn<.5?turn*2:(1-turn)*2;for(const [which,x,base]of [['A',mix(-580,-80,q),2],['B',mix(1020,540,q),0]]){const y=-75-exit*600,w=520,id=which==='A'?'head-a':'head-b';layer(c,f,id,t,[x,y,w,w*1.18],(X,Y,W,H)=>{const a=c.globalAlpha;for(const [view,opacity]of [[base,1-front],[1,front]]){const im=media(images,f,'feudHead'+which,view);if(im){c.globalAlpha=a*opacity;c.drawImage(im,X,Y,W,H);}}});eye(c,f,which==='A'?'eye-a':'eye-b',t,x+w*(which==='A'?.72:.28),y+w*.65);}}
function court(c,images,f,t){if(t<=658.6){paintTrial(c,trialDuration(f),images,{...f,trialIllustrationLabel:false});return;}const swap=span(t,658.6,659.4),pair=span(t,661.3,662),room=media(images,f,'feudCourt');if(room)c.drawImage(room,-36,-15,1013,570);if(swap<1){c.save();c.beginPath();c.rect(0,0,960*(1-swap),540);c.clip();pic(c,images,f,'feudWitnessA',t,mix(280,-800,swap),90,470);c.restore();}if(swap>0)pic(c,images,f,'feudWitnessB',t,mix(1080,260,swap),90,470);if(pair>0){pic(c,images,f,'feudWitnessA',t,mix(1080,470,pair),90,470);if(pair>.6)pic(c,images,f,'feudWitnessA',t,-350,90,470);}if(room)layer(c,f,'rail',t,[0,410,960,130],(x,y,w,h)=>c.drawImage(room,0,room.height*410/540,room.width,room.height*130/540,x,y,w,h));vignette(c);}
function factory(c,images,f,t){const enter=span(t,688.5,691.5),split=span(t,693.9,695.5),w=mix(430,440,split),y=mix(650,240,enter),im=media(images,f,'feudFactory');layer(c,f,'ground',t,[0,y+190,960,Math.max(1,540-y-190)],(x,Y,W,H)=>{const g=media(images,f,'feudGround');if(g){c.filter='grayscale(1) brightness(.65)';c.drawImage(g,0,g.height*.35,g.width,g.height*.65,x,Y,W,H);}});if(im)for(const i of [0,1]){if(i===1&&split===0)continue;const x=i===0?mix(480-w/2,30,split):mix(480-w/2,490,split);layer(c,f,i===0?'factory-a':'factory-b',t,[x,y,w,w*.5628],(X,Y,W,H)=>{if(i===1)c.scale(-1,1);const open=i===1?split:1;if(open<1){c.beginPath();c.rect(-W/2,Y,W*open,H);c.clip();}c.drawImage(im,X,Y,W,H);});}const logo=span(t,695.7,697);if(logo){c.save();c.globalAlpha=logo*.65;pic(c,images,f,'feudBrandA',t,135,125,210);pic(c,images,f,'feudBrandB',t,615,125,210);c.restore();}}
const fireCache=new WeakMap();function flameTile(im,n){let m=fireCache.get(im);if(!m)fireCache.set(im,m=new Map());if(m.has(n))return m.get(n);const cv=Object.assign(document.createElement('canvas'),{width:512,height:216}),c=cv.getContext('2d');c.drawImage(im,n%4*512,Math.floor(n/4)*288,512,216,0,0,512,216);c.globalCompositeOperation='destination-in';const g=c.createLinearGradient(0,140,0,216);g.addColorStop(0,'#fff');g.addColorStop(1,'#fff0');c.fillStyle=g;c.fillRect(0,0,512,216);m.set(n,cv);return cv;}
function flames(c,images,f,t,front){const im=media(images,f,'feudFire'),growth=span(t,699.2,704.5);if(!im||!growth)return;layer(c,f,front?'fire-front':'fire-back',t,[0,0,960,540],(x,y)=>{c.translate(x,y);c.globalCompositeOperation='screen';c.globalAlpha*=f.feudFireStrength*(front?.95:.65)*growth;for(let i=0;i<3;i++){const n=((Math.floor((t-699.2)*12)+i*5)%16+16)%16,W=front?620:650,H=mix(100,front?350:430,growth);c.save();c.translate(i*350-220,front?560-H:440-H);c.drawImage(f.feudSourceBindings.feudFire?im:flameTile(im,n),0,0,W,H);c.restore();}});}
function chapter(c,images,f,t){atmosphere(c,f,t,'title');const settle=span(t,710.0333333333333,712),retreat=span(t,712,718);layer(c,f,'chapter-shoes',t,[0,0,960,540],(x,y)=>{c.translate(x,y);for(let i=0;i<8;i++){const im=media(images,f,i%2?'feudShoeA':'feudShoeB');if(!im)continue;const a=i*2.399+(t-710)*.09,r=300+(i%3)*125,w=150*(.7+(i%3)*.24);c.save();c.translate(480+Math.cos(a)*r,260+Math.sin(a)*r*.68);c.rotate(a*.7+(t-710)*(.09+i*.01));c.filter=`blur(${i%3===0?3:.2}px)`;c.globalAlpha*=.75;c.drawImage(im,-w/2,-w*.28,w,w*.5628);c.restore();}});layer(c,f,'chapter-label',t,[150,215,660,28],()=>{c.font='700 20px Arial';c.textAlign='center';c.fillStyle='#fff';c.globalAlpha*=settle;c.fillText(f.feudChapter,0,0);});layer(c,f,'chapter-title',t,[20,240,920,80],()=>{const chars=[...f.feudTitle],fs=f.feudTitleSize*(1-retreat*.1);c.font=`800 ${fs}px Arial`;const widths=chars.map(a=>c.measureText(a).width),total=widths.reduce((a,b)=>a+b,0);c.scale(Math.min(1,900/total),Math.min(1,900/total));let xx=-total/2;chars.forEach((ch,i)=>{const q=span(t,710.0333333333333+i*.012,711.55+i*.012);c.save();c.translate(xx+widths[i]/2+Math.sin(i*17.3)*f.feudTitleScatter*(1-q),Math.cos(i*11.4)*120*(1-q));c.rotate(Math.sin(i*5.3)*(1-q)*1.7);c.filter=`blur(${(1-q)*f.feudTitleBlur}px)`;c.globalAlpha*=.2+.8*q;c.shadowColor='#f9c363';c.shadowBlur=12;c.fillStyle=f.feudTitleColor;c.textAlign='center';c.textBaseline='middle';c.fillText(ch,0,0);c.restore();xx+=widths[i];});});}
export function paintFeud(c,age,images,input={}){const f={...feudDefaults,...input},s=feudState(age,f),t=s.source;if(age<0||!f.feudEnabled)return s;c.save();c.canvas.sceneAssets=[];c.fillStyle='#000';c.fillRect(0,0,960,540);if(age===0){paintTrial(c,trialDuration(f),images,f);c.restore();return s;}if(t<662.7)court(c,images,f,t);else if(t<675.3){atmosphere(c,f,t,'split');collage(c,images,f,t);}else if(t<688.5){atmosphere(c,f,t);question(c,images,f,t);if(t>=682)heads(c,images,f,t);}else if(t<698.2666666666667){atmosphere(c,f,t,t>=695.5?'split':'red');if(t<690.3){question(c,images,f,t);heads(c,images,f,t);}factory(c,images,f,t);}else if(t<707.5){atmosphere(c,f,t,'split');flames(c,images,f,t,false);portrait(c,images,f,t,mix(2,.8,span(t,698.2666666666667,706)));flames(c,images,f,t,true);if(t>=706){c.fillStyle=`rgba(0,0,0,${span(t,706,707.5)})`;c.fillRect(0,0,960,540);}}else if(t<710.0333333333333){c.restore();return s;}else chapter(c,images,f,t);if(f.feudIllustrationLabel&&t<706)layer(c,f,'illustration-label',t,[18,505,924,18],(x,y)=>{c.fillStyle='#0009';c.fillRect(x-5,y-2,550,19);c.fillStyle='#e3e3dd';c.font='11px Arial';c.fillText('ILLUSTRATIVE RECONSTRUCTION · GENERATED PEOPLE / ENVIRONMENTS',x,y+11);});c.fillStyle='#000';c.fillRect(0,0,960,16);c.fillRect(0,524,960,16);c.restore();return s;}

export function paintFeudChapterTail(c,source,images,input={}){chapter(c,images,{...feudDefaults,...input},source);}
